def negative_count(arr):
    # Initialize a counter for negative numbers
    count = 0
    # Iterate through each number in the array
    for num in arr:
        # Check if the number is negative
        if num < 0:
            # Increment the counter if it is negative
            count += 1
    # Calculate the ratio of negative numbers to the total number of elements
    return count / len(arr)
