def is_Sub_Array(arr1, arr2, n1, n2):
    # Check if the length of arr2 is greater than n1
    if len(arr2) > n1:
        return False

    # Iterate through arr1
    for i in range(n1):
        # Check if the current element of arr1 matches the first element of arr2
        if arr1[i] == arr2[0]:
            # Check if the remaining elements of arr1 match the rest of arr2
            for j in range(1, n2):
                if arr1[i+j] != arr2[j]:
                    return False
    return True
